// CallableTool is a union that represents a tool that can be called by an agent. In Cadenya, a tool that is used within an agent objective
//
//	might be a user-defined tool (IE: MCP, HTTP), another Agent (useful to separate context), or a Cadenya Tool (one Cadenya provides).
//
// CallableTool is a oneOf union; at most one variant is non-nil. All variants
// nil means the union was unset (protobuf empty/default) in the response.
type CallableTool struct {
	Tool                *CallableTool_Tool                `json:"-"`
	Agent               *CallableTool_Agent               `json:"-"`
	CadenyaProvidedTool *CallableTool_CadenyaProvidedTool `json:"-"`
}

func (u CallableTool) MarshalJSON() ([]byte, error) {
	var chosen any
	count := 0
	if u.Tool != nil {
		chosen = u.Tool
		count++
	}
	if u.Agent != nil {
		chosen = u.Agent
		count++
	}
	if u.CadenyaProvidedTool != nil {
		chosen = u.CadenyaProvidedTool
		count++
	}
	if count == 0 {
		return []byte("{}"), nil
	}
	if count > 1 {
		return nil, fmt.Errorf("CallableTool: exactly one variant must be set, got %d", count)
	}
	return json.Marshal(chosen)
}

// NewCallableToolTool returns a CallableTool with the Tool variant selected.
func NewCallableToolTool(v CallableTool_Tool) CallableTool {
	v.Type = "tool"
	return CallableTool{Tool: &v}
}

// NewCallableToolAgent returns a CallableTool with the Agent variant selected.
func NewCallableToolAgent(v CallableTool_Agent) CallableTool {
	v.Type = "agent"
	return CallableTool{Agent: &v}
}

// NewCallableToolCadenyaProvidedTool returns a CallableTool with the CadenyaProvidedTool variant selected.
func NewCallableToolCadenyaProvidedTool(v CallableTool_CadenyaProvidedTool) CallableTool {
	v.Type = "cadenyaProvidedTool"
	return CallableTool{CadenyaProvidedTool: &v}
}

func (u *CallableTool) UnmarshalJSON(data []byte) error {
	*u = CallableTool{}
	var probe struct {
		Tag string `json:"type"`
	}
	if err := json.Unmarshal(data, &probe); err != nil {
		return err
	}
	if probe.Tag == "" {
		return nil
	}
	switch probe.Tag {
	case "tool":
		u.Tool = new(CallableTool_Tool)
		return json.Unmarshal(data, u.Tool)
	case "agent":
		u.Agent = new(CallableTool_Agent)
		return json.Unmarshal(data, u.Agent)
	case "cadenyaProvidedTool":
		u.CadenyaProvidedTool = new(CallableTool_CadenyaProvidedTool)
		return json.Unmarshal(data, u.CadenyaProvidedTool)
	}
	return fmt.Errorf("CallableTool: unknown type %q", probe.Tag)
}

